/** BoringUI's five text roles at both density steps, in whole pixels.
 * Shared by size-context, the Typography specimens, and the prose stylesheet. */
type TypeScaleVariant = "default" | "compact";
interface TypeScalePair {
  size: number;
  leading: number;
}
interface TypeScaleStep {
  default: number;
  compact: number;
}

const typeStyles = {
  display: { default: { size: 28, leading: 34 }, compact: { size: 24, leading: 30 } },
  title: { default: { size: 16, leading: 22 }, compact: { size: 15, leading: 20 } },
  subtitle: { default: { size: 14, leading: 20 }, compact: { size: 13, leading: 18 } },
  body: { default: { size: 13, leading: 20 }, compact: { size: 12, leading: 18 } },
  caption: { default: { size: 12, leading: 16 }, compact: { size: 11, leading: 14 } },
} as const satisfies Record<string, Record<TypeScaleVariant, TypeScalePair>>;

type TypeScaleRole = keyof typeof typeStyles;
const typeScale = Object.fromEntries(
  Object.entries(typeStyles).map(([role, step]) => [
    role,
    { default: step.default.size, compact: step.compact.size },
  ]),
) as Record<TypeScaleRole, TypeScaleStep>;

export { typeStyles, typeScale };
export type { TypeScaleRole, TypeScaleVariant, TypeScalePair, TypeScaleStep };
